/**
 * Metadados de todos os inputs: rótulo, unidade, faixa plausível, casas decimais
 * e tooltip com a definição da variável e a fonte do default.
 *
 * A chave é o caminho (dot-path) dentro do objeto Scenario. Este registro é a
 * fonte única usada pela UI, pelos solvers de equilíbrio, pelo gráfico tornado
 * e pela simulação de Monte Carlo.
 */
export type FieldKind = "num" | "pct" | "money" | "bool" | "select" | "text";

export interface FieldMeta {
  label: string;
  unit: string;
  tip: string;
  kind: FieldKind;
  min?: number;
  max?: number;
  dec?: number;
  options?: { value: string; label: string }[];
  /** Marcado como candidato natural a análise de sensibilidade. */
  sens?: boolean;
}

const n = (
  label: string,
  unit: string,
  min: number,
  max: number,
  tip: string,
  dec = 2,
  sens = false,
): FieldMeta => ({ label, unit, min, max, tip, dec, kind: "num", sens });

const m = (
  label: string,
  min: number,
  max: number,
  tip: string,
  sens = false,
): FieldMeta => ({ label, unit: "R$", min, max, tip, dec: 0, kind: "money", sens });

const p = (
  label: string,
  min: number,
  max: number,
  tip: string,
  dec = 1,
  sens = false,
): FieldMeta => ({ label, unit: "%", min, max, tip, dec, kind: "pct", sens });

const b = (label: string, tip: string): FieldMeta => ({
  label,
  unit: "",
  tip,
  kind: "bool",
});

const s = (
  label: string,
  options: { value: string; label: string }[],
  tip: string,
): FieldMeta => ({ label, unit: "", tip, kind: "select", options });

const t = (label: string, tip: string): FieldMeta => ({
  label,
  unit: "",
  tip,
  kind: "text",
});

