/** Acesso seguro a um campo por caminho. */
export const getField = (path: string): FieldMeta =>
  FIELDS[path] ?? { label: path, unit: "", tip: "Campo sem metadado declarado.", kind: "num", dec: 2 };

/** Todos os caminhos numéricos, usados por solvers, tornado e Monte Carlo. */
export const NUMERIC_PATHS = Object.keys(FIELDS).filter((k) => {
  const f = FIELDS[k];
  return f.kind === "num" || f.kind === "pct" || f.kind === "money";
});
